#!/usr/bin/env python3
import argparse,pathlib,subprocess,sys
p=argparse.ArgumentParser();p.add_argument('--ms',type=int,default=60000);p.add_argument('--tag',required=True);a=p.parse_args();d=pathlib.Path('tasks/minecraft/team/p2/iter32')
body=r'''
let dead=false,phaseListener=false,wet=0;const die=()=>{dead=true;bot.pathfinder.setGoal(null);bot.clearControlStates();};const keepFloat=()=>{if(bot.entity.isInWater||bot.blockAt(bot.entity.position.floored())?.name==='water')bot.setControlState('jump',true);};const sourceHP=bot.health;let reason='budget',lastAir=bot.entity.position.clone(),underSince=0;
console.log('SOURCE',JSON.stringify({...state(),faces:boundary(),kind:global.p2ShelterKind,time:bot.time.timeOfDay}));bot.on('death',die);
try{if(bot.health<15||!bot.inventory.items().some(i=>i.name==='wooden_sword'||(i.name==='stone_sword'||i.name==='wooden_sword')))throw Error('recovery source');if(global.p2ShelterKind==='afloat'){if(bot.blockAt(bot.entity.position.offset(0,bot.entity.eyeHeight,0).floored())?.name!=='air')throw Error('afloat source head');bot.setControlState('jump',true);await wait(20);}else if(global.p2ShelterKind==='buried'||global.p2ShelterKind==='carved'||global.p2ShelterKind==='box')await exitShelter();
const m=new Movements(bot);m.canDig=false;m.allowParkour=false;m.allow1by1towers=false;m.allowSprinting=true;m.maxDropDown=1;m.infiniteLiquidDropdownDistance=false;m.scafoldingBlocks=[];for(const n of['lava','powder_snow','sweet_berry_bush'])m.blocksToAvoid.add(bot.registry.blocksByName[n].id);m.exclusionAreasStep.push(b=>['lava','powder_snow','sweet_berry_bush'].includes(b.name)?Infinity:0);m.exclusionAreasStep.push(b=>{let cost=0;for(const e of Object.values(bot.entities)){if(!['spider','zombie','skeleton','creeper','witch'].includes(e.name)||Math.abs(e.position.y-b.position.y)>=4)continue;const next=Math.hypot(e.position.x-b.position.x-.5,e.position.z-b.position.z-.5),now=Math.hypot(e.position.x-bot.entity.position.x,e.position.z-bot.entity.position.z);if(next<12){if(now>=12||next<now-.25)return Infinity;cost+=2;}}return cost;});bot.pathfinder.setMovements(m);let goal=null;const target=(x=148,z=Math.min(1463,Math.floor(bot.entity.position.z)+80))=>{goal=new goals.GoalNearXZ(x,z,2);bot.pathfinder.setGoal(goal);console.log('NEXT_TARGET',JSON.stringify({at:new Date().toISOString(),x,z,state:state()}));};target();bot.on('physicsTick',keepFloat);phaseListener=true;await bot.equip(bot.inventory.items().find(i=>(i.name==='stone_sword'||i.name==='wooden_sword')),'hand');const t=Date.now();let checked=Date.now(),last=bot.entity.position.clone(),stalls=0,phase='';
while(Date.now()-t<MAXMS&&!dead&&bot.health>8&&bot.health>=sourceHP-6){const animals=[];if(animals.length&&!Object.values(bot.entities).some(e=>['spider','zombie','skeleton','creeper'].includes(e.name)&&e.position.distanceTo(bot.entity.position)<14)){console.log('ANIMAL_OPPORTUNITY',JSON.stringify(animals.map(e=>({id:e.id,n:e.name,p:e.position}))));reason='animals';break;}m.allowSprinting=bot.food>7;const p=bot.entity.position,head=bot.blockAt(p.offset(0,bot.entity.eyeHeight,0).floored())?.name,nowPhase=(bot.entity.isInWater?'WATER':'DRY')+'/'+head;if(bot.entity.isInWater)wet++;if(head==='air'){lastAir=p.clone();underSince=0;}else if(head==='water'){if(!underSince)underSince=Date.now();if(Date.now()-underSince>1800){console.log('SUBMERGED_RECOVERY',JSON.stringify(state()));await bot.lookAt(p.offset(0,3,0),true);await wait(1);const b=bot.blockAtCursor(4.4);if(b&&['ice','packed_ice','blue_ice'].includes(b.name)){await cut(b.position);}else{goal=new goals.GoalNearXZ(lastAir.x,lastAir.z,1);bot.pathfinder.setGoal(goal);}if(Date.now()-underSince>7000){reason='headwater';break;}}}
if(nowPhase!==phase){console.log('MOTION_PHASE',JSON.stringify({at:new Date().toISOString(),p:bot.entity.position,hp:bot.health,food:bot.food,phase:nowPhase,below:bot.blockAt(p.floored().offset(0,-1,0))?.name}));phase=nowPhase;}
if(p.z>=1460&&Math.abs(p.x-148)<5){reason='corpse_region';break;}if(goal.isEnd(p.floored()))target();const close=Object.values(bot.entities).some(e=>['spider','zombie','skeleton'].includes(e.name)&&e.position.distanceTo(p)<2.8);if(close){bot.pathfinder.setGoal(null);const hits=await defend(2400);console.log('DEFENSE_EFFECT',JSON.stringify({hits,state:state()}));bot.pathfinder.setGoal(goal);}
const food=(bot.food<=14?bot.inventory.items().find(i=>i.name==='cooked_beef'):null)||(bot.food<=18?bot.inventory.items().find(i=>i.name==='sweet_berries'):null);if(food&&bot.food<=18&&!Object.values(bot.entities).some(e=>['spider','zombie','skeleton','creeper'].includes(e.name)&&e.position.distanceTo(p)<12)){bot.pathfinder.setGoal(null);await bot.equip(food,'hand');await bot.consume();await wait(12);console.log('TRAVEL_FOOD',JSON.stringify(state()));await bot.equip(bot.inventory.items().find(i=>(i.name==='stone_sword'||i.name==='wooden_sword')),'hand');bot.pathfinder.setGoal(goal);}
if(Date.now()-checked>8000){if(!bot.inventory.items().some(i=>i.name.endsWith('_log')||i.name.endsWith('_planks'))){const logs=[];if(logs.length){console.log('WOOD_OPPORTUNITY',JSON.stringify(logs));reason='wood';break;}}const delta=p.distanceTo(last);console.log('PROGRESS',JSON.stringify({...state(),delta}));if(delta<1.5){stalls++;if(stalls>=3){reason='blocked';break;}target(Math.floor(p.x)+(stalls%2?24:-24),Math.min(1463,Math.floor(p.z)+50));}else stalls=0;last=p.clone();checked=Date.now();}await wait(2);}
if(dead)throw Error('death');if(bot.health<sourceHP-6||bot.health<=8)reason='health';bot.removeListener('physicsTick',keepFloat);phaseListener=false;bot.pathfinder.setGoal(null);bot.clearControlStates();if(!full(bot.entity.position.floored().offset(0,-1,0))&&bot.entity.isInWater)bot.setControlState('jump',true);await wait(12);console.log('TRAVEL_EFFECT',JSON.stringify({...state(),reason,wet}));
if(reason==='corpse_region'){console.log('ACTUAL_DROPS',JSON.stringify(Object.values(bot.entities).filter(e=>e.name==='item'&&e.position.distanceTo(bot.entity.position)<20).map(e=>({id:e.id,p:e.position}))));for(let k=0;k<12;k++){const e=Object.values(bot.entities).filter(e=>e.name==='item'&&e.position.distanceTo(bot.entity.position)<14).sort((a,b)=>a.position.distanceTo(bot.entity.position)-b.position.distanceTo(bot.entity.position))[0];if(!e)break;const g=new goals.GoalNearXZ(e.position.x,e.position.z,.6);bot.pathfinder.setGoal(g);const a=Date.now();while(Date.now()-a<1800&&!g.isEnd(bot.entity.position.floored())&&bot.health>6)await wait(2);bot.pathfinder.setGoal(null);await wait(10);}console.log('ACTUAL_RESCUE_RECEIPT',JSON.stringify(state()));}if(bot.entity.onGround&&full(bot.entity.position.floored().offset(0,-1,0)))await finishShelter();else{global.p2ShelterKind='afloat';bot.setControlState('jump',true);for(let k=0;k<10;k++){const head=bot.blockAt(bot.entity.position.offset(0,bot.entity.eyeHeight,0).floored())?.name;console.log('AFLOAT_ENDING',JSON.stringify({...state(),head,jump:bot.getControlState('jump')}));if(head!=='air')throw Error('afloat head not air');await wait(6);}}
const b=bot.inventory.items().find(i=>i.name==='sweet_berries');if(b&&bot.food<20){await bot.equip(b,'hand');await bot.consume();await wait(12);}console.log('END_OPERATION',JSON.stringify({...state(),faces:boundary(),kind:global.p2ShelterKind,reason}));
}catch(e){console.log('FAILURE',String(e),JSON.stringify(state()));if(!dead&&bot.entity.onGround&&!boundary().every(f=>f.full))try{await finishShelter();}catch(x){console.log('RECOVERY_FAILURE',String(x));}}finally{if(phaseListener)bot.removeListener('physicsTick',keepFloat);bot.pathfinder.setGoal(null);if(bot.entity.isInWater&&!bot.entity.onGround){bot.setControlState('forward',false);bot.setControlState('jump',true);}else bot.clearControlStates();bot.removeListener('death',die);}return {...state(),dead,reason,faces:boundary(),kind:global.p2ShelterKind};
'''.replace('MAXMS',str(a.ms))
f=d/(a.tag+'.js');f.write_text(''.join((d/n).read_text() for n in ['core.js','ending.js','box.js','carve_room.js','exit_shelter.js','defense.js'])+body)
sys.exit(subprocess.call([sys.executable,str(d/'run_p2.py'),'--timeout',str(a.ms//1000+50),'--out',str(d/(a.tag+'.out')),str(f)]))
